window.BOOK={"key":"sayrsaadi","app":"mutoon-sayrsaadi","lsk":"mutoon_sayrsaadi_v1","prefix":"sa_","title":"السير إلى الله والدار الآخرة","sub":"التزكية والرقائق · عبد الرحمن بن ناصر السعدي (ت ١٣٧٦هـ) · ١٧ بيتًا","poems":[{"id":"sayrsaadi","title":"السير إلى الله والدار الآخرة","nazim":"عبد الرحمن بن ناصر السعدي","death":"ت ١٣٧٦هـ","meter":"الكامل","source":"المكتبة الشاملة: موارد الظمآن لدروس الزمان لعبد العزيز السلمان (تلميذ الناظم)","srcUrl":"https://shamela.ws/book/7480/3272","note":"النص المشكول من «موارد الظمآن» للشيخ عبد العزيز السلمان تلميذ الناظم (١٧ بيتًا)، قوبل كلمةً كلمةً بسكربت بنصه في «مجموعة القصائد الزهديات» له وبنص شرح فؤاد أبو سعيد (موقع صيد الفوائد، ١٨ بيتًا). صُحّحت أخطاء الطباعة في الحركات من المصدرين الآخرين وأُكمل ما نقص، وكل شطر موزون على الكامل (البيتان ٢ و٥ بنقل حركة الهمزة بعد «قد»). البيت الزائد في نسخة الشرح بين ١٤ و١٥ محرَّف فيها فلم يُثبت.","verses":[["سَعِدَ الَّذِينَ تَجَنَّبُوا سُبُلَ الرَّدَى","وَتَيَمَّمُوا لِمَنَازِلِ الرِّضْوَانِ"],["فَهُمُ الَّذِينَ قَدْ أَخْلَصُوا فِي مَشْيِهِمْ","مُتَشَرِّعِينَ بِشِرْعَةِ الْإِيمَانِ"],["وَهُمُ الَّذِينَ بَنَوْا مَنَازِلَ سَيْرِهِمْ","بَيْنَ الرَّجَا وَالْخَوْفِ لِلدَّيَّانِ"],["وَهُمُ الَّذِينَ مَلَا الْإِلَهُ قُلُوبَهُمْ","بِوِدَادِهِ وَمَحَبَّةِ الرَّحْمَنِ"],["وَهُمُ الَّذِينَ قَدْ أَكْثَرُوا مِنْ ذِكْرِهِ","فِي السِّرِّ وَالْإِعْلَانِ وَالْأَحْيَانِ"],["يَتَقَرَّبُونَ إِلَى الْمَلِيكِ بِفِعْلِهِمْ","طَاعَاتِهِ وَالتَّرْكِ لِلْعِصْيَانِ"],["فِعْلُ الْفَرَائِضِ وَالنَّوَافِلِ دَأْبُهُمْ","مَعْ رُؤْيَةِ التَّقْصِيرِ وَالنُّقْصَانِ"],["صَبَرُوا النُّفُوسَ عَلَى الْمَكَارِهِ كُلِّهَا","شَوْقًا إِلَى مَا فِيهِ مِنْ إِحْسَانِ"],["نَزَلُوا بِمَنْزِلَةِ الرِّضَى فَهُمُ بِهَا","قَدْ أَصْبَحُوا فِي جُنَّةٍ وَأَمَانِ"],["شَكَرُوا الَّذِي أَوْلَى الْخَلَائِقَ فَضْلَهُ","بِالْقَلْبِ وَالْأَقْوَالِ وَالْأَرْكَانِ"],["صَحِبُوا التَّوَكُّلَ فِي جَمِيعِ أُمُورِهِمْ","مَعْ بَذْلِ جُهْدٍ فِي رِضَى الرَّحْمَنِ"],["عَبَدُوا الْإِلَهَ عَلَى اعْتِقَادِ حُضُورِهِ","فَتَبَوَّءُوا فِي مَنْزِلِ الْإِحْسَانِ"],["نَصَحُوا الْخَلِيقَةَ فِي رِضَى مَحْبُوبِهِمْ","بِالْعِلْمِ وَالْإِرْشَادِ وَالْإِحْسَانِ"],["صَحِبُوا الْخَلَائِقَ بِالْجُسُومِ وَإِنَّمَا","أَرْوَاحُهُمْ فِي مَنْزِلٍ فَوْقَانِي"],["عَزَفُوا الْقُلُوبَ عَنِ الشَّوَاغِلِ كُلِّهَا","قَدْ فَرَّغُوهَا مِنْ سِوَى الرَّحْمَنِ"],["حَرَكَاتُهُمْ وَهُمُومُهُمْ وَعُزُومُهُمْ","لِلَّهِ لَا لِلْخَلْقِ وَالشَّيْطَانِ"],["نِعْمَ الرَّفِيقُ لِطَالِبِ السُّبُلِ الَّتِي","تُفْضِي إِلَى الْخَيْرَاتِ وَالْإِحْسَانِ"]],"secs":{"1":"السير إلى الله والدار الآخرة"}}],"sharh":false};
